<script setup>
import {ref} from 'vue'
import {useData} from '../data'
import {t} from '../i18n'
import MetricCards from '../components/MetricCards.vue'
const days=ref(30),dashboard=useData(()=>'/api/v1/admin/dashboard?days='+days.value),calls=useData('/api/v1/calls?page=1&size=200')
</script><template><PageHeader title="overview" description="overviewHint"><el-select v-model="days" style="width:160px"><el-option v-for="value in [7,30,90]" :key="value" :value="value" :label="t('last'+value+'Days')"/></el-select></PageHeader><el-alert v-if="dashboard.error.value" :title="dashboard.error.value" type="error"/><MetricCards :data="dashboard.data.value?.period" :items="[{key:'calls',label:'periodCalls'},{key:'reached',label:'reachedCalls'},{key:'interested',label:'interestedLeads'},{key:'average_qa_score',label:'averageQaScore',suffix:'/ 100'}]"/><div class="split"><el-card :header="t('recentCalls')"><DataGrid :rows="(calls.data.value||[]).slice(0,6)" :columns="[{key:'phone',label:'phone'},{key:'mode',label:'mode',translate:true},{key:'status',label:'status',translate:true,tag:true},{key:'created_at',label:'createdAt',date:true}]"/><router-link to="/admin/calls"><el-button link>{{t('details')}}</el-button></router-link></el-card><el-card :header="t('quickActions')"><div class="flow-palette"><router-link v-for="[path,label] in [['contacts','addContact'],['scripts','createScript'],['campaigns','createCampaign'],['calls','startCall']]" :key="path" :to="'/admin/'+path"><el-button>{{t(label)}}</el-button></router-link></div></el-card></div><el-card :header="t('campaignPerformance')"><DataGrid :rows="dashboard.data.value?.campaign_performance" row-key="campaign_id" :columns="[{key:'campaign_id',label:'campaignId'},{key:'name',label:'name'},{key:'calls',label:'periodCalls'},{key:'reached',label:'reachedCalls'},{key:'reach_rate',label:'reachRate',render:v=>v+'%'},{key:'interested',label:'interestedLeads'},{key:'interest_rate',label:'interestRate',render:v=>v+'%'}]"/><p class="hint">{{dashboard.data.value?.metric_definitions?.reached}}；{{dashboard.data.value?.metric_definitions?.interested}}</p></el-card></template>
